1	{
2	  "name": "stockroom",
3	  "version": "0.0.0",
4	  "private": true,
5	  "type": "module",
6	  "engines": {
7	    "node": ">=24 <25"
8	  },
9	  "scripts": {
10	    "start": "node app.ts"
11	  },
12	  "bin": {
13	    "stockroom": "app.ts"
14	  }
15	}
16

1	#!/usr/bin/env node
2	// stockroom —— 本地多仓库存台账（Node.js 24，TypeScript，无外部运行依赖）
3	
4	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
5	import { join } from 'node:path';
6	
7	const APP_NAME = 'stockroom';
8	const DATA_FILENAME = 'stockroom.json';
9	const DEFAULT_DATA_DIR = '.stockroom';
10	
11	class UsageError extends Error {} // 命令行用法错误 -> 退出码 2
12	class BizError extends Error {} // 业务拒绝 -> 退出码 1
13	class DataError extends Error {} // 数据读取/保存失败 -> 退出码 1
14	
15	type DocType = 'in' | 'out' | 'transfer';
16	type EntryType =
17	  | DocType
18	  | 'count'
19	  | 'arrival'
20	  | 'return'
21	  | 'in-rev'
22	  | 'out-rev'
23	  | 'transfer-rev'
24	  | 'count-rev'
25	  | 'arrival-rev'
26	  | 'return-rev';
27	
28	interface LedgerEntry {
29	  seq: number; // 全局流水序号，即提交顺序
30	  doc: string; // 单据编号（冲销流水此处为冲销单编号）
31	  type: EntryType;
32	  product: string;
33	  wh: string; // 本流水条目变动余量的仓库（到货为采购单收货仓）
34	  qty?: number; // 入库/出库/调拨/到货类流水：恒为正数，方向由类型 / 出入仓决定；盘点类流水不用此字段
35	  before: number;
36	  after: number;
37	  from?: string; // 调拨（或冲销调拨）的调出仓
38	  to?: string; // 调拨（或冲销调拨）的调入仓
39	  po?: string; // 到货/退货流水：所属采购单编号
40	  arr?: string; // 退货（及冲销退货）流水：原到货单编号
41	  orig?: string; // 冲销流水：被冲销的原单编号
42	  expected?: number; // 盘点（及冲销盘点）流水：预期账面量
43	  actual?: number; // 盘点（及冲销盘点）流水：实盘量
44	  diff?: number; // 盘点差额 = 实盘 - 账面（可正、可负、可零）；冲销盘点流水记录原差额
45	}
46	
47	interface DocRecord {
48	  content: Record<string, unknown>; // 规范化业务内容（明细顺序无关）
49	  resultLines: string[]; // 原提交结果，供幂等重放
50	}
51	
52	interface ReversalRecord {
53	  orig: string; // 被冲销的原单编号
54	  resultLines: string[]; // 冲销提交结果，供幂等重放
55	}
56	
57	interface PurchaseRecord {
58	  poId: string;
59	  supplier: string;
60	  wh: string; // 收货仓
61	  ordered: Record<string, number>; // 商品 -> 订购量（合并后，正安全整数）
62	  resultLines: string[]; // 登记结果，供幂等重放
63	}
64	
65	interface ArrivalRecord {
66	  poId: string; // 所属采购单
67	  wh: string; // 采购单收货仓（冗余自采购单，便于校验与展示）
68	  qty: Record<string, number>; // 本次到货：商品 -> 数量（合并后，正安全整数）
69	  resultLines: string[]; // 到货提交结果，供幂等重放
70	}
71	
72	interface CancelRecord {
73	  poId: string; // 所属采购单
74	  qty: Record<string, number>; // 本次取消：商品 -> 数量（合并后，正安全整数）
75	  resultLines: string[]; // 取消提交结果，供幂等重放
76	}
77	
78	interface ReturnRecord {
79	  arrId: string; // 原到货单编号
80	  poId: string; // 所属采购单（冗余自原到货单，便于校验与展示）
81	  wh: string; // 原到货单收货仓（退货从该仓当前余量扣减）
82	  qty: Record<string, number>; // 本次退货：商品 -> 数量（合并后，正安全整数）
83	  resultLines: string[]; // 退货提交结果，供幂等重放
84	}
85	
86	interface ReplenishRule {
87	  min: number; // 下限：预计量不高于此值才触发补货（非负安全整数）
88	  target: number; // 目标：补货缺口 = 目标 - 预计量（非负安全整数，恒大于下限）
89	}
90	
91	interface Store {
92	  version: 1;
93	  products: Record<string, string>; // 编号 -> 名称（编号区分大小写；null 原型，防特殊键串改）
94	  stock: Record<string, Record<string, number>>; // 商品 -> 仓库 -> 余量
95	  entries: LedgerEntry[];
96	  docs: Record<string, DocRecord>; // 入库/出库/调拨/盘点单去重与结果
97	  reversals: Record<string, ReversalRecord>; // 冲销单去重与结果（可冲销到货单、取消单、退货单）
98	  purchases: Record<string, PurchaseRecord>; // 采购单登记（独立编号空间，不改库存）
99	  arrivals: Record<string, ArrivalRecord>; // 到货单去重与结果（与库存单共用编号空间）
100	  cancels: Record<string, CancelRecord>; // 取消单去重与结果（与库存单共用编号空间，不改库存与流水）
101	  returns: Record<string, ReturnRecord>; // 退货单去重与结果（与库存单共用编号空间）
102	  rules: Record<string, Record<string, ReplenishRule>>; // 补货规则：商品 -> 仓库 -> 下限/目标（每组合唯一）
103	}
104	
105	const REV_ENTRY_TYPES = new Set<EntryType>([
106	  'in-rev', 'out-rev', 'transfer-rev', 'count-rev', 'arrival-rev', 'return-rev',
107	]);
108	
109	function nullProto<T extends object>(): T {
110	  return Object.create(null) as T;
111	}
112	
113	function emptyStore(): Store {
114	  return {
115	    version: 1,
116	    products: nullProto(),
117	    stock: nullProto(),
118	    entries: [],
119	    docs: nullProto(),
120	    reversals: nullProto(),
121	    purchases: nullProto(),
122	    arrivals: nullProto(),
123	    cancels: nullProto(),
124	    returns: nullProto(),
125	    rules: nullProto(),
126	  };
127	}
128	
129	// ---------- 工具 ----------
130	
131	function isPlainObject(v: unknown): v is Record<string, unknown> {
132	  return typeof v === 'object' && v !== null && !Array.isArray(v);
133	}
134	
135	function isNonNegSafeInt(v: unknown): v is number {
136	  return typeof v === 'number' && Number.isSafeInteger(v) && v >= 0;
137	}
138	
139	function isPosSafeInt(v: unknown): v is number {
140	  return typeof v === 'number' && Number.isSafeInteger(v) && v > 0;
141	}
142	
143	function trimOrThrow(label: string, raw: string): string {
144	  const s = raw.trim();
145	  if (s === '') throw new BizError(`${label}去除首尾空白后不能为空`);
146	  return s;
147	}
148	
149	/** 规范化序列化：对象键排序，保证业务内容比较与明细顺序无关。 */
150	function stableStringify(v: unknown): string {
151	  if (isPlainObject(v)) {
152	    return (
153	      '{' +
154	      Object.keys(v)
155	        .sort()
156	        .map((k) => JSON.stringify(k) + ':' + stableStringify(v[k]))
157	        .join(',') +
158	      '}'
159	    );
160	  }
161	  if (Array.isArray(v)) return '[' + v.map(stableStringify).join(',') + ']';
162	  return JSON.stringify(v);
163	}
164	
165	// ---------- 数据持久化 ----------
166	
167	function dataPath(dataDir: string): string {
168	  return join(dataDir, DATA_FILENAME);
169	}
170	
171	function loadStore(dataDir: string): Store {
172	  let raw: string;
173	  try {
174	    raw = readFileSync(dataPath(dataDir), 'utf8');
175	  } catch (e) {
176	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyStore(); // 尚不存在 -> 空库
177	    throw new DataError(`无法读取数据文件 ${dataPath(dataDir)}：${(e as Error).message}`);
178	  }
179	
180	  let data: unknown;
181	  try {
182	    // JSON.parse 将 "__proto__" 保留为普通自有属性（不设置原型）；随后 validateStore
183	    // 会把全部容器重新装入 null 原型对象，constructor 等特殊键同样安全。
184	    data = JSON.parse(raw);
185	  } catch {
186	    throw new DataError(`数据文件已损坏，无法解析 JSON：${dataPath(dataDir)}（不会作为空库覆盖）`);
187	  }
188	  return validateStore(data);
189	}
190	
191	function validateStore(data: unknown): Store {
192	  const bad = (msg: string): DataError =>
193	    new DataError(`数据文件已损坏或格式不正确（${msg}），拒绝启动以免覆盖原数据`);
194	
195	  if (!isPlainObject(data)) throw bad('根节点不是对象');
196	  if (data.version !== 1) throw bad(`不支持的数据版本：${String(data.version)}`);
197	
198	  // 重新装入 null 原型容器：即使磁盘数据来自普通对象，constructor/__proto__ 等键也安全
199	  const store = emptyStore();
200	
201	  if (!isPlainObject(data.products)) throw bad('products 不是对象');
202	  for (const [id, name] of Object.entries(data.products)) {
203	    if (typeof id !== 'string' || id.trim() === '' || typeof name !== 'string')
204	      throw bad('products 中存在非法编号或名称');
205	    store.products[id] = name;
206	  }
207	
208	  if (!isPlainObject(data.stock)) throw bad('stock 不是对象');
209	  for (const [pid, whs] of Object.entries(data.stock)) {
210	    if (!isPlainObject(whs)) throw bad(`商品 ${pid} 的库存不是对象`);
211	    const whMap = nullProto<Record<string, number>>();
212	    for (const [wh, qty] of Object.entries(whs)) {
213	      if (typeof wh !== 'string' || wh.trim() === '' || !isNonNegSafeInt(qty))
214	        throw bad(`商品 ${pid} 仓库 ${String(wh)} 的余量非法`);
215	      whMap[wh] = qty;
216	    }
217	    store.stock[pid] = whMap;
218	  }
219	
220	  if (!Array.isArray(data.entries)) throw bad('entries 不是数组');
221	  let lastSeq = 0;
222	  for (const e of data.entries as unknown[]) {
223	    if (!isPlainObject(e)) throw bad('存在非法流水条目');
224	    if (!isPosSafeInt(e.seq) || e.seq !== ++lastSeq) throw bad('流水序号不连续');
225	    if (typeof e.doc !== 'string' || e.doc.trim() === '') throw bad('流水缺少单据编号');
226	    const isRev = REV_ENTRY_TYPES.has(e.type as EntryType);
227	    const isOrig =
228	      e.type === 'in' || e.type === 'out' || e.type === 'transfer' || e.type === 'count' ||
229	      e.type === 'arrival' || e.type === 'return';
230	    if (!isRev && !isOrig) throw bad('流水类型非法');
231	    if (typeof e.product !== 'string' || e.product.trim() === '') throw bad('流水缺少商品编号');
232	    if (typeof e.wh !== 'string' || e.wh.trim() === '') throw bad('流水缺少仓库标识');
233	    if (!isNonNegSafeInt(e.before) || !isNonNegSafeInt(e.after)) throw bad('流水余量非法');
234	    if (e.type === 'count' || e.type === 'count-rev') {
235	      if (!isNonNegSafeInt(e.expected) || !isNonNegSafeInt(e.actual))
236	        throw bad('盘点流水账面/实盘量非法');
237	      if (typeof e.diff !== 'number' || !Number.isSafeInteger(e.diff)) throw bad('盘点流水差额非法');
238	      if (e.diff !== e.actual - e.expected) throw bad('盘点流水差额与账面、实盘量不一致');
239	      const applied = e.type === 'count' ? e.diff : -e.diff; // 冲销盘点应用反向差额
240	      if (e.after - e.before !== applied) throw bad('盘点流水差额与前后余量不一致');
241	      if (e.qty !== undefined || e.from !== undefined || e.to !== undefined || e.po !== undefined ||
242	          e.arr !== undefined)
243	        throw bad('盘点流水不应携带数量、调拨、采购或退货字段');
244	    } else {
245	      if (!isPosSafeInt(e.qty)) throw bad('流水数量非法');
246	      if (e.expected !== undefined || e.actual !== undefined || e.diff !== undefined)
247	        throw bad('非盘点流水不应携带盘点字段');
248	      const delta = e.after - e.before;
249	      if (e.type === 'transfer' || e.type === 'transfer-rev') {
250	        if (typeof e.from !== 'string' || e.from.trim() === '' || typeof e.to !== 'string' || e.to.trim() === '')
251	          throw bad('调拨流水缺少调出/调入仓');
252	        if (e.po !== undefined || e.arr !== undefined) throw bad('调拨流水不应携带采购或退货字段');
253	        // 调拨：调入仓增加；冲销调拨：原调入仓扣回、原调出仓补回
254	        const expect = (e.wh === e.to) === (e.type === 'transfer') ? e.qty : -e.qty;
255	        if (delta !== expect) throw bad('流水差额与前后余量不一致');
256	      } else {
257	        if (e.from !== undefined || e.to !== undefined) throw bad('非调拨流水不应携带调拨字段');
258	        // 到货入收货仓、冲销退货补回为增；退货从收货仓扣减、冲销到货扣回为减
259	        const increases =
260	          e.type === 'in' || e.type === 'out-rev' || e.type === 'arrival' || e.type === 'return-rev';
261	        if (delta !== (increases ? e.qty : -e.qty)) throw bad('流水差额与前后余量不一致');
262	        if (e.type === 'arrival' || e.type === 'arrival-rev') {
263	          if (typeof e.po !== 'string' || e.po.trim() === '') throw bad('到货流水缺少采购单编号');
264	          if (e.arr !== undefined) throw bad('到货流水不应携带原到货单字段');
265	        } else if (e.type === 'return' || e.type === 'return-rev') {
266	          if (typeof e.po !== 'string' || e.po.trim() === '') throw bad('退货流水缺少采购单编号');
267	          if (typeof e.arr !== 'string' || e.arr.trim() === '') throw bad('退货流水缺少原到货单编号');
268	        } else if (e.po !== undefined || e.arr !== undefined) {
269	          throw bad('非到货/退货流水不应携带采购或退货字段');
270	        }
271	      }
272	    }
273	    if (isRev) {
274	      if (typeof e.orig !== 'string' || e.orig.trim() === '') throw bad('冲销流水缺少原单编号');
275	    } else if (e.orig !== undefined) {
276	      throw bad('原始单据流水不应携带冲销标记');
277	    }
278	    store.entries.push(e as unknown as LedgerEntry);
279	  }
280	
281	  if (!isPlainObject(data.docs)) throw bad('docs 不是对象');
282	  for (const [docId, rec] of Object.entries(data.docs)) {
283	    if (typeof docId !== 'string' || docId.trim() === '') throw bad('存在非法单据编号');
284	    if (!isPlainObject(rec) || !isPlainObject(rec.content) || !Array.isArray(rec.resultLines))
285	      throw bad(`单据 ${docId} 的去重记录非法`);
286	    if (!rec.resultLines.every((l) => typeof l === 'string')) throw bad(`单据 ${docId} 的结果记录非法`);
287	    const c = rec.content;
288	    if (c.type !== 'in' && c.type !== 'out' && c.type !== 'transfer' && c.type !== 'count')
289	      throw bad(`单据 ${docId} 的业务类型非法`);
290	    if (!isPlainObject(c.items)) throw bad(`单据 ${docId} 的明细非法`);
291	    for (const [pid, item] of Object.entries(c.items)) {
292	      if (pid.trim() === '') throw bad(`单据 ${docId} 存在非法明细`);
293	      if (c.type === 'count') {
294	        if (!isPlainObject(item) || !isNonNegSafeInt(item.expected) || !isNonNegSafeInt(item.actual))
295	          throw bad(`单据 ${docId} 存在非法盘点明细`);
296	      } else if (!isPosSafeInt(item)) {
297	        throw bad(`单据 ${docId} 存在非法明细`);
298	      }
299	    }
300	    if (c.type === 'transfer') {
301	      if (typeof c.from !== 'string' || c.from.trim() === '' || typeof c.to !== 'string' || c.to.trim() === '')
302	        throw bad(`单据 ${docId} 的调拨仓非法`);
303	    } else if (typeof c.wh !== 'string' || c.wh.trim() === '') {
304	      throw bad(`单据 ${docId} 的仓库非法`);
305	    }
306	    store.docs[docId] = rec as unknown as DocRecord;
307	  }
308	
309	  // purchases 为新增字段：合法旧数据没有该字段，按空集合处理。
310	  // 采购单编号独立于库存单据编号空间，允许与入库/到货/冲销单同名。
311	  if (data.purchases !== undefined) {
312	    if (!isPlainObject(data.purchases)) throw bad('purchases 不是对象');
313	    for (const [poId, rec] of Object.entries(data.purchases)) {
314	      if (typeof poId !== 'string' || poId.trim() === '') throw bad('存在非法采购单编号');
315	      if (
316	        !isPlainObject(rec) ||
317	        typeof rec.supplier !== 'string' || rec.supplier.trim() === '' ||
318	        typeof rec.wh !== 'string' || rec.wh.trim() === '' ||
319	        !isPlainObject(rec.ordered) ||
320	        !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string')
321	      )
322	        throw bad(`采购单 ${poId} 的记录非法`);
323	      if (rec.poId !== undefined && rec.poId !== poId) throw bad(`采购单 ${poId} 的内嵌编号不一致`);
324	      const ordered = nullProto<Record<string, number>>();
325	      for (const [pid, qty] of Object.entries(rec.ordered)) {
326	        if (pid.trim() === '' || !isPosSafeInt(qty)) throw bad(`采购单 ${poId} 存在非法订购明细`);
327	        ordered[pid] = qty;
328	      }
329	      if (Object.keys(ordered).length === 0) throw bad(`采购单 ${poId} 至少需要一种商品`);
330	      store.purchases[poId] = {
331	        poId, supplier: rec.supplier, wh: rec.wh, ordered, resultLines: rec.resultLines,
332	      };
333	    }
334	  }
335	
336	  // arrivals 为新增字段：合法旧数据没有该字段，按空集合处理。
337	  // 到货单与入库/出库/调拨/盘点/冲销单共用全局唯一编号空间。
338	  if (data.arrivals !== undefined) {
339	    if (!isPlainObject(data.arrivals)) throw bad('arrivals 不是对象');
340	    for (const [arrId, rec] of Object.entries(data.arrivals)) {
341	      if (typeof arrId !== 'string' || arrId.trim() === '') throw bad('存在非法到货单编号');
342	      if (store.docs[arrId] !== undefined) throw bad(`到货单编号 ${arrId} 与原始库存单据编号冲突`);
343	      if (
344	        !isPlainObject(rec) ||
345	        typeof rec.poId !== 'string' || rec.poId.trim() === '' ||
346	        typeof rec.wh !== 'string' || rec.wh.trim() === '' ||
347	        !isPlainObject(rec.qty) ||
348	        !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string')
349	      )
350	        throw bad(`到货单 ${arrId} 的记录非法`);
351	      const qty = nullProto<Record<string, number>>();
352	      for (const [pid, q] of Object.entries(rec.qty)) {
353	        if (pid.trim() === '' || !isPosSafeInt(q)) throw bad(`到货单 ${arrId} 存在非法到货明细`);
354	        qty[pid] = q;
355	      }
356	      if (Object.keys(qty).length === 0) throw bad(`到货单 ${arrId} 至少需要一种商品`);
357	      const po = store.purchases[rec.poId];
358	      if (po === undefined) throw bad(`到货单 ${arrId} 指向的采购单 ${rec.poId} 不存在`);
359	      if (rec.wh !== po.wh) throw bad(`到货单 ${arrId} 的收货仓与采购单 ${rec.poId} 不一致`);
360	      for (const [pid, q] of Object.entries(qty)) {
361	        if (po.ordered[pid] === undefined)
362	          throw bad(`到货单 ${arrId} 含采购单 ${rec.poId} 未订购的商品 ${pid}`);
363	        if (q > po.ordered[pid])
364	          throw bad(`到货单 ${arrId} 商品 ${pid} 到货量超过订购量`);
365	      }
366	      store.arrivals[arrId] = { poId: rec.poId, wh: rec.wh, qty, resultLines: rec.resultLines };
367	    }
368	  }
369	
370	  // cancels 为新增字段：合法旧数据没有该字段，按空集合处理。
371	  // 取消单与入库/出库/调拨/盘点/到货/冲销单共用全局唯一编号空间；
372	  // 取消只减少待收承诺，不改库存、不产生库存流水。
373	  if (data.cancels !== undefined) {
374	    if (!isPlainObject(data.cancels)) throw bad('cancels 不是对象');
375	    for (const [canId, rec] of Object.entries(data.cancels)) {
376	      if (typeof canId !== 'string' || canId.trim() === '') throw bad('存在非法取消单编号');
377	      if (store.docs[canId] !== undefined) throw bad(`取消单编号 ${canId} 与原始库存单据编号冲突`);
378	      if (store.arrivals[canId] !== undefined) throw bad(`取消单编号 ${canId} 与到货单编号冲突`);
379	      if (
380	        !isPlainObject(rec) ||
381	        typeof rec.poId !== 'string' || rec.poId.trim() === '' ||
382	        !isPlainObject(rec.qty) ||
383	        !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string')
384	      )
385	        throw bad(`取消单 ${canId} 的记录非法`);
386	      const qty = nullProto<Record<string, number>>();
387	      for (const [pid, q] of Object.entries(rec.qty)) {
388	        if (pid.trim() === '' || !isPosSafeInt(q)) throw bad(`取消单 ${canId} 存在非法取消明细`);
389	        qty[pid] = q;
390	      }
391	      if (Object.keys(qty).length === 0) throw bad(`取消单 ${canId} 至少需要一种商品`);
392	      const po = store.purchases[rec.poId];
393	      if (po === undefined) throw bad(`取消单 ${canId} 指向的采购单 ${rec.poId} 不存在`);
394	      for (const [pid, q] of Object.entries(qty)) {
395	        if (po.ordered[pid] === undefined)
