407	  if (data.returns !== undefined) {
408	    if (!isPlainObject(data.returns)) throw bad('returns 不是对象');
409	    for (const [retId, rec] of Object.entries(data.returns)) {
410	      if (typeof retId !== 'string' || retId.trim() === '') throw bad('存在非法退货单编号');
411	      if (store.docs[retId] !== undefined) throw bad(`退货单编号 ${retId} 与原始库存单据编号冲突`);
412	      if (store.arrivals[retId] !== undefined) throw bad(`退货单编号 ${retId} 与到货单编号冲突`);
413	      if (store.cancels[retId] !== undefined) throw bad(`退货单编号 ${retId} 与取消单编号冲突`);
414	      if (
415	        !isPlainObject(rec) ||
416	        typeof rec.arrId !== 'string' || rec.arrId.trim() === '' ||
417	        typeof rec.poId !== 'string' || rec.poId.trim() === '' ||
418	        typeof rec.wh !== 'string' || rec.wh.trim() === '' ||
419	        !isPlainObject(rec.qty) ||
420	        !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string')
421	      )
422	        throw bad(`退货单 ${retId} 的记录非法`);
423	      const qty = nullProto<Record<string, number>>();
424	      for (const [pid, q] of Object.entries(rec.qty)) {
425	        if (pid.trim() === '' || !isPosSafeInt(q)) throw bad(`退货单 ${retId} 存在非法退货明细`);
426	        qty[pid] = q;
427	      }
428	      if (Object.keys(qty).length === 0) throw bad(`退货单 ${retId} 至少需要一种商品`);
429	      const arr = store.arrivals[rec.arrId];
430	      if (arr === undefined) throw bad(`退货单 ${retId} 指向的原到货单 ${rec.arrId} 不存在`);
431	      if (rec.poId !== arr.poId) throw bad(`退货单 ${retId} 的采购单与原到货单 ${rec.arrId} 不一致`);
432	      if (rec.wh !== arr.wh) throw bad(`退货单 ${retId} 的收货仓与原到货单 ${rec.arrId} 不一致`);
433	      for (const [pid, q] of Object.entries(qty)) {
434	        if (arr.qty[pid] === undefined)
435	          throw bad(`退货单 ${retId} 含原到货单 ${rec.arrId} 没有的商品 ${pid}`);
436	        if (q > arr.qty[pid]) throw bad(`退货单 ${retId} 商品 ${pid} 退货量超过原到货量`);
437	      }
438	      store.returns[retId] = { arrId: rec.arrId, poId: rec.poId, wh: rec.wh, qty, resultLines: rec.resultLines };
439	    }
440	  }
441	
442	  // reversals 为新增字段：合法旧数据没有该字段，按空集合处理。
443	  // 原单既可以是入库/出库/调拨/盘点单，也可以是到货单、取消单、退货单；冲销单不可冲销。
444	  if (data.reversals !== undefined) {
445	    if (!isPlainObject(data.reversals)) throw bad('reversals 不是对象');
446	    for (const [revId, rec] of Object.entries(data.reversals)) {
447	      if (typeof revId !== 'string' || revId.trim() === '') throw bad('存在非法冲销单编号');
448	      if (!isPlainObject(rec) || typeof rec.orig !== 'string' || rec.orig.trim() === '' ||
449	          !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string'))
450	        throw bad(`冲销单 ${revId} 的记录非法`);
451	      if (store.docs[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与原始库存单据编号冲突`);
452	      if (store.arrivals[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与到货单编号冲突`);
453	      if (store.cancels[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与取消单编号冲突`);
454	      if (store.returns[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与退货单编号冲突`);
455	      const origRec = store.docs[rec.orig];
456	      const origArr = store.arrivals[rec.orig];
457	      const origCan = store.cancels[rec.orig];
458	      const origRet = store.returns[rec.orig];
459	      if (origRec === undefined && origArr === undefined && origCan === undefined && origRet === undefined) {
460	        // 用 data.reversals 判定，避免依赖键的先后顺序（此时 store.reversals 可能尚未装全）
461	        if (isPlainObject((data.reversals as Record<string, unknown>)[rec.orig]))
462	          throw bad(`冲销单 ${rec.orig} 不可被再次冲销（冲销单不能冲销冲销单）`);
463	        if (store.purchases[rec.orig] !== undefined)
464	          throw bad(`冲销单 ${revId} 指向的 ${rec.orig} 是采购单，采购单不可冲销`);
465	        throw bad(`冲销单 ${revId} 指向的原单 ${rec.orig} 不存在`);
466	      }
467	      store.reversals[revId] = { orig: rec.orig, resultLines: rec.resultLines };
468	    }
469	    // 每张原单最多被成功冲销一次（库存单与到货单统一校验）
470	    const origSeen = nullProto<Record<string, string>>();
471	    for (const [revId, rec] of Object.entries(store.reversals)) {
472	      if (origSeen[rec.orig] !== undefined)
473	        throw bad(`原单 ${rec.orig} 被多张冲销单关联（${origSeen[rec.orig]}、${revId}）`);
474	      origSeen[rec.orig] = revId;
475	    }
476	    // 冲销单不可冲销：冲销关系不能指向另一张冲销单
477	    for (const rec of Object.values(store.reversals)) {
478	      if (store.reversals[rec.orig] !== undefined)
479	        throw bad(`冲销单 ${rec.orig} 不可被再次冲销`);
480	    }
481	    // 冲销流水必须能找到所属冲销单
482	    for (const e of store.entries) {
483	      if (REV_ENTRY_TYPES.has(e.type) && store.reversals[e.doc] === undefined)
484	        throw bad(`流水引用了不存在的冲销单 ${e.doc}`);
485	    }
486	  }
487	
488	  // 到货流水必须能找到所属到货单，且逐项数量/采购单/收货仓与记录一致；
489	  // 逐商品合计用 BigInt 精确累计，避免多条流水合计超过安全整数范围时舍入误判
490	  const arrivalEntrySeen = nullProto<Record<string, Record<string, bigint>>>();
491	  for (const e of store.entries) {
492	    if (e.type !== 'arrival') continue;
493	    const arr = store.arrivals[e.doc];
494	    if (arr === undefined) throw bad(`流水引用了不存在的到货单 ${e.doc}`);
495	    if (e.po !== arr.poId) throw bad(`到货单 ${e.doc} 流水的采购单编号与记录不一致`);
496	    if (e.wh !== arr.wh) throw bad(`到货单 ${e.doc} 流水的收货仓与记录不一致`);
497	    const perProduct = (arrivalEntrySeen[e.doc] ??= nullProto<Record<string, bigint>>());
498	    perProduct[e.product] = (perProduct[e.product] ?? 0n) + BigInt(e.qty!);
499	  }
500	  for (const [arrId, arr] of Object.entries(store.arrivals)) {
501	    const seen = arrivalEntrySeen[arrId];
502	    if (seen === undefined) throw bad(`到货单 ${arrId} 缺少到货流水`);
503	    for (const [pid, q] of Object.entries(arr.qty)) {
504	      if (seen[pid] !== BigInt(q)) throw bad(`到货单 ${arrId} 商品 ${pid} 的流水数量与记录不一致`);
505	    }
506	    for (const pid of Object.keys(seen)) {
507	      if (arr.qty[pid] === undefined) throw bad(`到货单 ${arrId} 的流水含记录中没有的商品 ${pid}`);
508	    }
509	  }
510	
511	  // 冲销到货流水逐项数量必须与原到货单一致
512	  for (const e of store.entries) {
513	    if (e.type !== 'arrival-rev') continue;
514	    const rev = store.reversals[e.doc];
515	    if (rev === undefined) throw bad(`冲销到货流水引用了不存在的冲销单 ${e.doc}`);
516	    const arr = store.arrivals[rev.orig];
517	    if (arr === undefined) throw bad(`冲销单 ${e.doc} 指向的到货原单 ${rev.orig} 不存在`);
518	    if (e.po !== arr.poId) throw bad(`冲销单 ${e.doc} 流水的采购单编号与原到货单不一致`);
519	    if (arr.qty[e.product] !== e.qty)
520	      throw bad(`冲销单 ${e.doc} 商品 ${e.product} 的冲销量与原到货单不一致`);
521	  }
522	
523	  // 退货流水必须能找到所属退货单，且逐项数量/原到货单/采购单/收货仓与记录一致（合计同样精确累计）
524	  const returnEntrySeen = nullProto<Record<string, Record<string, bigint>>>();
525	  for (const e of store.entries) {
526	    if (e.type !== 'return') continue;
527	    const ret = store.returns[e.doc];
528	    if (ret === undefined) throw bad(`流水引用了不存在的退货单 ${e.doc}`);
529	    if (e.arr !== ret.arrId) throw bad(`退货单 ${e.doc} 流水的原到货单编号与记录不一致`);
530	    if (e.po !== ret.poId) throw bad(`退货单 ${e.doc} 流水的采购单编号与记录不一致`);
531	    if (e.wh !== ret.wh) throw bad(`退货单 ${e.doc} 流水的收货仓与记录不一致`);
532	    const perProduct = (returnEntrySeen[e.doc] ??= nullProto<Record<string, bigint>>());
533	    perProduct[e.product] = (perProduct[e.product] ?? 0n) + BigInt(e.qty!);
534	  }
535	  for (const [retId, ret] of Object.entries(store.returns)) {
536	    const seen = returnEntrySeen[retId];
537	    if (seen === undefined) throw bad(`退货单 ${retId} 缺少退货流水`);
538	    for (const [pid, q] of Object.entries(ret.qty)) {
539	      if (seen[pid] !== BigInt(q)) throw bad(`退货单 ${retId} 商品 ${pid} 的流水数量与记录不一致`);
540	    }
541	    for (const pid of Object.keys(seen)) {
542	      if (ret.qty[pid] === undefined) throw bad(`退货单 ${retId} 的流水含记录中没有的商品 ${pid}`);
543	    }
544	  }
545	
546	  // 冲销退货流水逐项数量必须与原退货单一致
547	  for (const e of store.entries) {
548	    if (e.type !== 'return-rev') continue;
549	    const rev = store.reversals[e.doc];
550	    if (rev === undefined) throw bad(`冲销退货流水引用了不存在的冲销单 ${e.doc}`);
551	    const ret = store.returns[rev.orig];
552	    if (ret === undefined) throw bad(`冲销单 ${e.doc} 指向的退货原单 ${rev.orig} 不存在`);
553	    if (e.arr !== ret.arrId) throw bad(`冲销单 ${e.doc} 流水的原到货单编号与原退货单不一致`);
554	    if (e.po !== ret.poId) throw bad(`冲销单 ${e.doc} 流水的采购单编号与原退货单不一致`);
555	    if (ret.qty[e.product] !== e.qty)
556	      throw bad(`冲销单 ${e.doc} 商品 ${e.product} 的冲销量与原退货单不一致`);
557	  }
558	
559	  // 退货不变量：同一原到货单的未冲销累计退货不得超过原到货量；
560	  // 有未冲销退货的到货单禁止冲销（已冲销到货的全部退货必须已冲销）
561	  for (const [retId, ret] of Object.entries(store.returns)) {
562	    const retReversed = Object.values(store.reversals).some((r) => r.orig === retId);
563	    if (retReversed) continue;
564	    if (Object.values(store.reversals).some((r) => r.orig === ret.arrId))
565	      throw bad(`到货单 ${ret.arrId} 已整单冲销，但其退货单 ${retId} 未冲销（有未冲销退货的到货单禁止冲销）`);
566	    const arr = store.arrivals[ret.arrId];
567	    const sumByPid = nullProto<Record<string, bigint>>();
568	    for (const [otherId, other] of Object.entries(store.returns)) {
569	      if (other.arrId !== ret.arrId) continue;
570	      if (Object.values(store.reversals).some((r) => r.orig === otherId)) continue;
571	      for (const [pid, q] of Object.entries(other.qty)) sumByPid[pid] = (sumByPid[pid] ?? 0n) + BigInt(q);
572	    }
573	    for (const [pid, sum] of Object.entries(sumByPid)) {
574	      if (sum > BigInt(arr.qty[pid]))
575	        throw bad(`到货单 ${ret.arrId} 商品 ${pid} 未冲销累计退货 ${sum} 超过原到货量 ${arr.qty[pid]}`);
576	    }
577	  }
578	
579	  // 冲销流水类型必须与原单业务类型一致（入库→in-rev、到货→arrival-rev、退货→return-rev 等）；
580	  // 取消单冲销不产生库存流水（取消本身不改库存），故不要求、也不允许携带流水。
581	  const revIdsWithEntries = nullProto<Record<string, boolean>>();
582	  for (const [revId, rev] of Object.entries(store.reversals)) {
583	    const origDoc = store.docs[rev.orig];
584	    // 原单为取消单时（前面已确认必为库存单/到货单/取消单/退货单之一）不应存在任何冲销流水
585	    let expected: EntryType | undefined;
586	    if (origDoc !== undefined) expected = `${origDoc.content.type}-rev` as EntryType;
587	    else if (store.arrivals[rev.orig] !== undefined) expected = 'arrival-rev';
588	    else if (store.returns[rev.orig] !== undefined) expected = 'return-rev';
589	    for (const e of store.entries) {
590	      if (e.doc !== revId) continue;
591	      if (expected === undefined)
592	        throw bad(`冲销单 ${revId} 冲销的是取消单 ${rev.orig}，不应携带库存流水`);
593	      revIdsWithEntries[revId] = true;
594	      if (e.type !== expected)
595	        throw bad(`冲销单 ${revId} 的流水类型与原单 ${rev.orig} 的业务类型不一致`);
596	    }
597	    if (expected !== undefined) revIdsWithEntries[revId] ??= false;
598	  }
599	  for (const revId of Object.keys(store.reversals)) {
600	    if (revIdsWithEntries[revId] === false) throw bad(`冲销单 ${revId} 缺少冲销流水`);
601	  }
602	
603	  // 采购进度不变量：有效到货 = 未冲销到货 - 未冲销退货；任一商品
604	  // “有效到货 + 未冲销累计取消”不得超过订购量
605	  // （待到货量 = 订购量 - 有效到货量 - 有效取消量，不得为负）。
606	  // 注意：退货释放待到货后允许再次到货，故未冲销到货总量本身可以超过订购量，
607	  // 甚至可以超过安全整数范围（反复退货、补收）——必须先抵减未冲销退货再校验，
608	  // 且全程用 BigInt 精确累计，不得因中间累计舍入而改变净量或误拒合法数据。
609	  for (const [poId, po] of Object.entries(store.purchases)) {
610	    const arrived = nullProto<Record<string, bigint>>();
611	    for (const [arrId, arr] of Object.entries(store.arrivals)) {
612	      if (arr.poId !== poId) continue;
613	      const isReversed = Object.values(store.reversals).some((r) => r.orig === arrId);
614	      if (isReversed) continue; // 已整单冲销的到货不再计入有效到货
615	      for (const [pid, q] of Object.entries(arr.qty)) {
616	        arrived[pid] = (arrived[pid] ?? 0n) + BigInt(q);
617	      }
618	    }
619	    // 未冲销退货抵减有效到货（前面已保证其原到货单未冲销且不超退）
620	    for (const [retId, ret] of Object.entries(store.returns)) {
621	      if (ret.poId !== poId) continue;
622	      const isReversed = Object.values(store.reversals).some((r) => r.orig === retId);
623	      if (isReversed) continue;
624	      for (const [pid, q] of Object.entries(ret.qty)) {
625	        arrived[pid] = (arrived[pid] ?? 0n) - BigInt(q);
626	        if (arrived[pid] < 0n)
627	          throw bad(`采购单 ${poId} 商品 ${pid} 未冲销累计退货超过有效到货量`);
628	      }
629	    }
630	    for (const [pid, q] of Object.entries(arrived)) {
631	      if (q > BigInt(po.ordered[pid] ?? 0))
632	        throw bad(`采购单 ${poId} 商品 ${pid} 有效到货（未冲销到货减未冲销退货）超过订购量`);
633	    }
634	    const cancelled = nullProto<Record<string, bigint>>();
635	    for (const [canId, can] of Object.entries(store.cancels)) {
636	      if (can.poId !== poId) continue;
637	      const isReversed = Object.values(store.reversals).some((r) => r.orig === canId);
638	      if (isReversed) continue; // 已整单冲销的取消不再计入有效取消
639	      for (const [pid, q] of Object.entries(can.qty)) {
640	        cancelled[pid] = (cancelled[pid] ?? 0n) + BigInt(q);
641	        if ((arrived[pid] ?? 0n) + cancelled[pid] > BigInt(po.ordered[pid]))
642	          throw bad(`采购单 ${poId} 商品 ${pid} 有效到货与有效取消合计超过订购量（待到货量为负）`);
643	      }
644	    }
645	  }
