647	  // rules 为新增字段：合法旧数据没有该字段，按无规则处理。
648	  // 规则按（商品, 仓库）唯一存放；商品必须已登记，仓库无需登记；
649	  // 下限与目标均为非负安全整数且下限小于目标，非法规则视为损坏数据，拒绝读取与覆盖。
650	  if (data.rules !== undefined) {
651	    if (!isPlainObject(data.rules)) throw bad('rules 不是对象');
652	    for (const [pid, whs] of Object.entries(data.rules)) {
653	      if (typeof pid !== 'string' || pid.trim() === '') throw bad('rules 中存在非法商品编号');
654	      if (store.products[pid] === undefined) throw bad(`补货规则指向未登记商品 ${pid}`);
655	      if (!isPlainObject(whs)) throw bad(`商品 ${pid} 的补货规则不是对象`);
656	      const whMap = nullProto<Record<string, ReplenishRule>>();
657	      for (const [wh, rule] of Object.entries(whs)) {
658	        if (typeof wh !== 'string' || wh.trim() === '')
659	          throw bad(`商品 ${pid} 的补货规则存在非法仓库标识`);
660	        if (
661	          !isPlainObject(rule) ||
662	          !isNonNegSafeInt(rule.min) ||
663	          !isNonNegSafeInt(rule.target) ||
664	          rule.min >= rule.target
665	        )
666	          throw bad(`商品 ${pid} 仓库 ${wh} 的补货规则非法（下限与目标须为非负安全整数且下限小于目标）`);
667	        whMap[wh] = { min: rule.min, target: rule.target };
668	      }
669	      if (Object.keys(whMap).length === 0) throw bad(`商品 ${pid} 的补货规则为空`);
670	      store.rules[pid] = whMap;
671	    }
672	  }
