677	function saveStore(dataDir: string, store: Store): void {
678	  const path = dataPath(dataDir);
679	  const tmp = join(dataDir, `.${DATA_FILENAME}.${process.pid}.tmp`);
680	  try {
681	    mkdirSync(dataDir, { recursive: true });
682	    writeFileSync(tmp, JSON.stringify(store, null, 2) + '\n', 'utf8');
683	    renameSync(tmp, path);
684	  } catch (e) {
685	    throw new DataError(`保存数据失败，已有数据保持不变：${(e as Error).message}`);
686	  }
687	}
