689	// ---------- 参数解析 ----------
690	
691	interface ParsedArgs {
692	  positionals: string[];
693	  flags: Record<string, string>;
694	  multi: Record<string, string[]>;
695	}
696	
697	function parseArgs(
698	  tokens: string[],
699	  singles: string[],
700	  multis: string[] = [],
701	): ParsedArgs {
702	  const out: ParsedArgs = { positionals: [], flags: {}, multi: {} };
703	  const singleSet = new Set(singles);
704	  const multiSet = new Set(multis);
705	
706	  for (let i = 0; i < tokens.length; i++) {
707	    const tok = tokens[i];
708	    if (tok.startsWith('--')) {
709	      let key = tok;
710	      let value: string | undefined;
711	      const eq = tok.indexOf('=');
712	      if (eq >= 0) {
713	        key = tok.slice(0, eq);
714	        value = tok.slice(eq + 1);
715	      }
716	      if (!singleSet.has(key) && !multiSet.has(key)) throw new UsageError(`未知参数：${tok}`);
717	      if (value === undefined) {
718	        if (i + 1 >= tokens.length) throw new UsageError(`参数 ${key} 缺少取值`);
719	        value = tokens[++i];
720	      }
721	      if (multiSet.has(key)) (out.multi[key] ??= []).push(value);
722	      else if (out.flags[key] !== undefined) throw new UsageError(`参数 ${key} 重复指定`);
723	      else out.flags[key] = value;
724	    } else {
725	      out.positionals.push(tok);
726	    }
727	  }
728	  return out;
729	}
730	
731	function parseItem(raw: string, merged: Map<string, number>): void {
732	  const idx = raw.indexOf(':');
733	  if (idx <= 0) throw new BizError(`明细格式应为 “商品编号:数量”：${raw}`);
734	  const pid = trimOrThrow('商品编号', raw.slice(0, idx));
735	  const qtyRaw = raw.slice(idx + 1).trim();
736	  if (!/^\d+$/.test(qtyRaw)) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
737	  const qty = Number(qtyRaw);
738	  if (!Number.isSafeInteger(qty) || qty <= 0) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
739	  const sum = (merged.get(pid) ?? 0) + qty; // 同单同商品先合并
740	  if (!Number.isSafeInteger(sum)) throw new BizError(`商品 ${pid} 累计数量超出安全整数范围`);
741	  merged.set(pid, sum);
742	}
