744	interface DocRequest {
745	  type: DocType;
746	  docId: string;
747	  wh?: string;
748	  from?: string;
749	  to?: string;
750	  items: Map<string, number>;
751	}
752	
753	function parseDocArgs(type: DocType, tokens: string[]): DocRequest {
754	  const args = parseArgs(tokens, type === 'transfer' ? ['--from', '--to'] : ['--wh'], ['--item']);
755	  const docId = args.positionals[0];
756	  if (docId === undefined || args.positionals.length !== 1)
757	    throw new UsageError(`用法：单据命令需要且仅需要一个单据编号`);
758	
759	  const items = new Map<string, number>();
760	  for (const raw of args.multi['--item'] ?? []) parseItem(raw, items);
761	  if (items.size === 0) throw new UsageError('单据至少需要一条 --item 商品编号:数量 明细');
762	
763	  const req: DocRequest = { type, docId: trimOrThrow('单据编号', docId), items };
764	  if (type === 'transfer') {
765	    if (args.flags['--from'] === undefined || args.flags['--to'] === undefined)
766	      throw new UsageError('调拨单必须提供 --from <调出仓> 与 --to <调入仓>');
767	    req.from = trimOrThrow('调出仓标识', args.flags['--from']);
768	    req.to = trimOrThrow('调入仓标识', args.flags['--to']);
769	    if (req.from === req.to) throw new BizError('调拨单的调出仓与调入仓不能相同');
770	  } else {
771	    if (args.flags['--wh'] === undefined) throw new UsageError('入库/出库单必须提供 --wh <仓库>');
772	    req.wh = trimOrThrow('仓库标识', args.flags['--wh']);
773	  }
774	  return req;
775	}
776	
777	interface CountItem {
778	  expected: number; // 预期账面量
779	  actual: number; // 实盘量
780	}
781	
782	interface CountRequest {
783	  docId: string;
784	  wh: string;
785	  items: Map<string, CountItem>;
786	}
787	
788	function parseNonNegInt(label: string, raw: string): number {
789	  const s = raw.trim();
790	  if (!/^\d+$/.test(s)) throw new BizError(`${label}必须为非负安全整数：${raw}`);
791	  const n = Number(s);
792	  if (!Number.isSafeInteger(n)) throw new BizError(`${label}必须为非负安全整数：${raw}`);
793	  return n;
794	}
795	
796	function parseCountArgs(tokens: string[]): CountRequest {
797	  const args = parseArgs(tokens, ['--wh'], ['--item']);
798	  const docId = args.positionals[0];
799	  if (docId === undefined || args.positionals.length !== 1)
800	    throw new UsageError('用法：count <单据编号> --wh <仓库> --item <商品编号:预期账面量:实盘量> [...]');
801	  if (args.flags['--wh'] === undefined) throw new UsageError('盘点单必须提供 --wh <仓库>');
802	
803	  const items = new Map<string, CountItem>();
804	  for (const raw of args.multi['--item'] ?? []) {
805	    const parts = raw.split(':');
806	    if (parts.length !== 3)
807	      throw new BizError(`盘点明细格式应为 “商品编号:预期账面量:实盘量”：${raw}`);
808	    const pid = trimOrThrow('商品编号', parts[0]);
809	    const expected = parseNonNegInt(`商品 ${pid} 的预期账面量`, parts[1]);
810	    const actual = parseNonNegInt(`商品 ${pid} 的实盘量`, parts[2]);
811	    if (items.has(pid)) throw new BizError(`盘点单中商品 ${pid} 重复出现，拒绝提交`);
812	    items.set(pid, { expected, actual });
813	  }
814	  if (items.size === 0)
815	    throw new UsageError('盘点单至少需要一条 --item 商品编号:预期账面量:实盘量 明细');
816	
817	  return { docId: trimOrThrow('单据编号', docId), wh: trimOrThrow('仓库标识', args.flags['--wh']), items };
818	}
