914	// ---------- 整批导入文件解析 ----------
915	
916	type ImportRequest =
917	  | { kind: 'doc'; req: DocRequest }
918	  | { kind: 'count'; req: CountRequest }
919	  | { kind: 'reverse'; docId: string; orig: string }
920	  | { kind: 'po'; req: PurchaseRequest }
921	  | { kind: 'arrival'; req: ArrivalRequest }
922	  | { kind: 'cancel'; req: CancelRequest }
923	  | { kind: 'return'; req: ReturnRequest };
924	
925	/** 读取导入文件：无法读取属于读写失败（退出 1），不改变任何已提交状态。 */
926	function readImportFile(file: string): string {
927	  try {
928	    return readFileSync(file, 'utf8');
929	  } catch (e) {
930	    throw new DataError(`无法读取导入文件 ${file}：${(e as Error).message}（不会改变任何已提交数据）`);
931	  }
932	}
933	
934	/**
935	 * 解析整批导入文件。文件级结构错误（非合法 JSON、根不是数组、空列表）属于文件
936	 * 格式错误（退出 2）；逐项格式不合法属于业务拒绝（退出 1），指出位置与原因。
937	 */
938	function parseImportFile(raw: string): ImportRequest[] {
939	  let data: unknown;
940	  try {
941	    data = JSON.parse(raw);
942	  } catch (e) {
943	    throw new UsageError(`导入文件不是合法 JSON：${(e as Error).message}`);
944	  }
945	  if (!Array.isArray(data)) throw new UsageError('导入文件格式错误：根节点必须是单据对象组成的有序数组');
946	  if (data.length === 0) throw new UsageError('导入文件格式错误：单据列表至少包含一项');
947	
948	  const out: ImportRequest[] = [];
949	  // 顶层位置一律标注 1 起序号，便于纠正
950	  const at = (i: number, msg: string): BizError => new BizError(`第 ${i + 1} 项：${msg}`);
951	
952	  const requireString = (obj: Record<string, unknown>, key: string, label: string, i: number): string => {
953	    const v = obj[key];
954	    if (v === undefined) throw at(i, `缺少${label}字段 "${key}"`);
955	    if (typeof v !== 'string') throw at(i, `${label}字段 "${key}" 必须是字符串`);
956	    const s = v.trim();
957	    if (s === '') throw at(i, `${label}去除首尾空白后不能为空`);
958	    return s;
959	  };
960	
961	  const checkUnknown = (obj: Record<string, unknown>, allowed: readonly string[], i: number): void => {
962	    for (const k of Object.keys(obj)) {
963	      if (!allowed.includes(k)) throw at(i, `含不支持的字段 "${k}"（允许字段：${allowed.join('、')}）`);
964	    }
965	  };
966	
967	  const parseQtyItems = (obj: Record<string, unknown>, i: number): Map<string, number> => {
968	    const v = obj.items;
969	    if (v === undefined) throw at(i, '缺少商品明细字段 "items"');
970	    if (!Array.isArray(v)) throw at(i, '"items" 必须是明细对象数组');
971	    if (v.length === 0) throw at(i, '商品明细至少一项');
972	    const merged = new Map<string, number>();
973	    v.forEach((entry, j) => {
974	      if (!isPlainObject(entry)) throw at(i, `第 ${j + 1} 条明细不是对象`);
975	      const e = entry as Record<string, unknown>;
976	      checkUnknown(e, ['product', 'qty'], i);
977	      const pid = e.product;
978	      if (typeof pid !== 'string') throw at(i, `第 ${j + 1} 条明细缺少商品编号字段 "product" 或不是字符串`);
979	      const p = pid.trim();
980	      if (p === '') throw at(i, `第 ${j + 1} 条明细的商品编号去空白后不能为空`);
981	      if (!isPosSafeInt(e.qty)) throw at(i, `商品 ${p} 的数量必须为正安全整数`);
982	      const sum = (merged.get(p) ?? 0) + (e.qty as number); // 同单同商品先合并
983	      if (!Number.isSafeInteger(sum)) throw at(i, `商品 ${p} 累计数量超出安全整数范围`);
984	      merged.set(p, sum);
985	    });
986	    return merged;
987	  };
988	
989	  const parseCountItems = (obj: Record<string, unknown>, i: number): Map<string, CountItem> => {
990	    const v = obj.items;
991	    if (v === undefined) throw at(i, '缺少商品明细字段 "items"');
992	    if (!Array.isArray(v)) throw at(i, '"items" 必须是明细对象数组');
993	    if (v.length === 0) throw at(i, '商品明细至少一项');
994	    const items = new Map<string, CountItem>();
995	    v.forEach((entry, j) => {
996	      if (!isPlainObject(entry)) throw at(i, `第 ${j + 1} 条明细不是对象`);
997	      const e = entry as Record<string, unknown>;
998	      checkUnknown(e, ['product', 'expected', 'actual'], i);
999	      const pid = e.product;
1000	      if (typeof pid !== 'string') throw at(i, `第 ${j + 1} 条明细缺少商品编号字段 "product" 或不是字符串`);
1001	      const p = pid.trim();
1002	      if (p === '') throw at(i, `第 ${j + 1} 条明细的商品编号去空白后不能为空`);
1003	      if (!isNonNegSafeInt(e.expected)) throw at(i, `商品 ${p} 的预期账面量必须为非负安全整数`);
1004	      if (!isNonNegSafeInt(e.actual)) throw at(i, `商品 ${p} 的实盘量必须为非负安全整数`);
1005	      if (items.has(p)) throw at(i, `盘点明细中商品 ${p} 重复出现，拒绝提交`); // 盘点不合并
1006	      items.set(p, { expected: e.expected, actual: e.actual });
1007	    });
1008	    return items;
1009	  };
1010	
1011	  data.forEach((rawItem, i) => {
1012	    if (!isPlainObject(rawItem)) throw at(i, '不是单据对象');
1013	    const item = rawItem as Record<string, unknown>;
1014	    if (item.type === undefined) throw at(i, '缺少业务类型字段 "type"');
1015	    if (typeof item.type !== 'string') throw at(i, '业务类型字段 "type" 必须是字符串');
1016	
1017	    switch (item.type) {
1018	      case 'in':
1019	      case 'out': {
1020	        checkUnknown(item, ['type', 'id', 'wh', 'items'], i);
1021	        const docId = requireString(item, 'id', '单据编号', i);
1022	        const wh = requireString(item, 'wh', '仓库标识', i);
1023	        out.push({ kind: 'doc', req: { type: item.type, docId, wh, items: parseQtyItems(item, i) } });
1024	        break;
1025	      }
1026	      case 'transfer': {
1027	        checkUnknown(item, ['type', 'id', 'from', 'to', 'items'], i);
1028	        const docId = requireString(item, 'id', '单据编号', i);
1029	        const from = requireString(item, 'from', '调出仓标识', i);
1030	        const to = requireString(item, 'to', '调入仓标识', i);
1031	        if (from === to) throw at(i, '调拨单的调出仓与调入仓不能相同');
1032	        out.push({ kind: 'doc', req: { type: 'transfer', docId, from, to, items: parseQtyItems(item, i) } });
1033	        break;
1034	      }
1035	      case 'count': {
1036	        checkUnknown(item, ['type', 'id', 'wh', 'items'], i);
1037	        const docId = requireString(item, 'id', '单据编号', i);
1038	        const wh = requireString(item, 'wh', '仓库标识', i);
1039	        out.push({ kind: 'count', req: { docId, wh, items: parseCountItems(item, i) } });
1040	        break;
1041	      }
1042	      case 'reverse': {
1043	        checkUnknown(item, ['type', 'id', 'orig'], i);
1044	        const docId = requireString(item, 'id', '冲销单编号', i);
1045	        const orig = requireString(item, 'orig', '原单编号', i);
1046	        out.push({ kind: 'reverse', docId, orig });
1047	        break;
1048	      }
1049	      case 'po': {
1050	        checkUnknown(item, ['type', 'id', 'supplier', 'wh', 'items'], i);
1051	        const poId = requireString(item, 'id', '采购编号', i);
1052	        const supplier = requireString(item, 'supplier', '供应商名称', i);
1053	        const wh = requireString(item, 'wh', '收货仓标识', i);
1054	        out.push({ kind: 'po', req: { poId, supplier, wh, items: parseQtyItems(item, i) } });
1055	        break;
1056	      }
1057	      case 'arrival': {
1058	        checkUnknown(item, ['type', 'id', 'po', 'items'], i);
1059	        const arrId = requireString(item, 'id', '到货单编号', i);
1060	        const poId = requireString(item, 'po', '采购编号', i);
1061	        out.push({ kind: 'arrival', req: { arrId, poId, items: parseQtyItems(item, i) } });
1062	        break;
1063	      }
1064	      case 'cancel': {
1065	        checkUnknown(item, ['type', 'id', 'po', 'items'], i);
1066	        const canId = requireString(item, 'id', '取消单编号', i);
1067	        const poId = requireString(item, 'po', '采购编号', i);
1068	        out.push({ kind: 'cancel', req: { canId, poId, items: parseQtyItems(item, i) } });
1069	        break;
1070	      }
1071	      case 'return': {
1072	        checkUnknown(item, ['type', 'id', 'arrival', 'items'], i);
1073	        const retId = requireString(item, 'id', '退货单编号', i);
1074	        const arrId = requireString(item, 'arrival', '原到货单编号', i);
1075	        out.push({ kind: 'return', req: { retId, arrId, items: parseQtyItems(item, i) } });
1076	        break;
1077	      }
1078	      default:
1079	        throw at(i, `不支持的业务类型 "${String(item.type)}"，只允许 in、out、transfer、count、reverse、po、arrival、cancel、return`);
1080	    }
1081	  });
1082	
1083	  return out;
1084	}
