1459	    if (po === undefined) throw new BizError(`采购单 ${req.poId} 不存在，拒绝取消`);
1460	
1461	    for (const [pid] of req.items) {
1462	      if (this.base.products[pid] === undefined) throw new BizError(`商品未登记，拒绝整单：${pid}`);
1463	      if (po.ordered[pid] === undefined)
1464	        throw new BizError(`商品 ${pid} 不在采购单 ${req.poId} 的订购明细内，拒绝整单`);
1465	    }
1466	
