1468	    const cancelledBefore = this.effectiveCancelled(req.poId); // 未冲销累计取消
1469	    const pids = [...req.items.keys()].sort();
1470	
1471	    // 先整单校验：任一商品本次取消量超过当前待到货量则整单拒绝、不登记任何取消
1472	    for (const pid of pids) {
