1936	  private applyArrivalReversal(revId: string, origId: string, origArr: ArrivalRecord): ApplyOutcome {
1937	    if (this.reversedOrigs.has(origId)) {
1938	      let existingRev = '';
1939	      for (const [r, rec] of Object.entries(this.revs)) {
1940	        if (rec.orig === origId) {
1941	          existingRev = r;
1942	          break;
1943	        }
1944	      }
1945	      throw new BizError(`到货原单 ${origId} 已被冲销单 ${existingRev} 成功冲销，每张到货单只能冲销一次`);
1946	    }
1947	
1948	    // 有未冲销退货的到货单禁止冲销；相关退货全部冲销后才可按原规则冲销到货
1949	    for (const [retId, ret] of Object.entries(this.returns)) {
1950	      if (ret.arrId === origId && !this.reversedOrigs.has(retId))
1951	        throw new BizError(`到货单 ${origId} 存在未冲销的退货单 ${retId}，禁止冲销；请先冲销全部相关退货`);
1952	    }
1953	
1954	    const poId = origArr.poId;
1955	    const wh = origArr.wh;
1956	    const po = this.pos[poId];
1957	    const pids = Object.keys(origArr.qty).sort();
1958	    const reportLines: string[] = [];
1959	    const arrivedBefore = this.effectiveArrived(poId); // 不含本到货单：其尚未被冲销，仍计入
1960	    const cancelledBefore = this.effectiveCancelled(poId); // 未冲销累计取消
1961	
1962	    // 先整单校验扣回可行性：任一商品不足则不登记任何变动
1963	    for (const pid of pids) {
1964	      const qty = origArr.qty[pid];
1965	      const before = getStock(this.draft, pid, wh);
1966	      if (before < qty)
1967	        throw new BizError(
1968	          `冲销到货原单 ${origId}：商品 ${pid} 收货仓 ${wh} 当前余量 ${before} 不足扣回 ${qty}，拒绝整单`,
1969	        );
1970	    }
1971	
1972	    for (const pid of pids) {
1973	      const qty = origArr.qty[pid];
1974	      const before = getStock(this.draft, pid, wh);
1975	      const after = before - qty;
1976	      setStock(this.draft, pid, wh, after);
1977	      this.additions.push({
1978	        seq: ++this.seq, doc: revId, type: 'arrival-rev', product: pid, wh,
1979	        qty, before, after, po: poId, orig: origId,
1980	      });
