2201	  in: '入库',
2202	  out: '出库',
2203	  transfer: '调拨',
2204	  count: '盘点',
2205	  arrival: '到货',
2206	  return: '退货',
2207	  'in-rev': '冲销入库',
2208	  'out-rev': '冲销出库',
2209	  'transfer-rev': '冲销调拨',
2210	  'count-rev': '冲销盘点',
