2215	function formatEntry(e: LedgerEntry): string {
2216	  let line: string;
2217	  if (e.type === 'count' || e.type === 'count-rev') {
2218	    const applied = e.type === 'count' ? e.diff! : -e.diff!; // 冲销盘点应用反向差额
2219	    line =
2220	      `#${e.seq}\t单据=${e.doc}\t${TYPE_LABEL[e.type]}\t商品=${e.product}\t仓库=${e.wh}` +
2221	      `\t差额=${fmtSigned(applied)}\t${e.before}->${e.after}\t账面=${e.expected}\t实盘=${e.actual}`;
2222	  } else {
2223	    let signed: string;
2224	    // 符号必须与前后余量一致：入库/冲销出库/到货/冲销退货/调入方向为增，其余为减
2225	    const increases =
2226	      e.type === 'in' || e.type === 'out-rev' || e.type === 'arrival' || e.type === 'return-rev' ||
2227	      ((e.type === 'transfer' || e.type === 'transfer-rev') &&
2228	        (e.type === 'transfer') === (e.wh === e.to));
2229	    signed = `${increases ? '+' : '-'}${e.qty}`;
2230	    line = `#${e.seq}\t单据=${e.doc}\t${TYPE_LABEL[e.type]}\t商品=${e.product}\t仓库=${e.wh}\t${signed}\t${e.before}->${e.after}`;
2231	    if (e.type === 'transfer' || e.type === 'transfer-rev') line += `\t调拨=${e.from}->${e.to}`;
2232	    if (e.po !== undefined) line += `\t采购单=${e.po}`;
2233	    if (e.arr !== undefined) line += `\t原到货单=${e.arr}`;
2234	  }
2235	  if (e.orig !== undefined) line += `\t原单=${e.orig}`;
2236	  return line;
2237	}
