2292	/**
2293	 * 计算采购单各商品的有效到货（未冲销到货-未冲销退货）、有效退货、有效取消与待到货量。
2294	 * 累计总量可超过安全整数范围（反复退货、补收），一律用 BigInt 精确累计，
2295	 * 合计与记录枚举顺序无关；有效退货合计即使超过安全整数范围也能完整显示。
2296	 */
2297	function purchaseProgress(store: Store, poId: string): {
2298	  effective: Record<string, bigint>;
2299	  returned: Record<string, bigint>;
2300	  cancelled: Record<string, bigint>;
2301	  remaining: Record<string, bigint>;
2302	} {
2303	  const effective = nullProto<Record<string, bigint>>();
2304	  for (const [arrId, arr] of Object.entries(store.arrivals)) {
2305	    if (arr.poId !== poId) continue;
2306	    const isReversed = Object.values(store.reversals).some((r) => r.orig === arrId);
2307	    if (isReversed) continue;
2308	    for (const [pid, q] of Object.entries(arr.qty)) effective[pid] = (effective[pid] ?? 0n) + BigInt(q);
2309	  }
2310	  const returned = nullProto<Record<string, bigint>>();
2311	  for (const [retId, ret] of Object.entries(store.returns)) {
2312	    if (ret.poId !== poId) continue;
2313	    const isReversed = Object.values(store.reversals).some((r) => r.orig === retId);
2314	    if (isReversed) continue;
2315	    for (const [pid, q] of Object.entries(ret.qty)) {
2316	      returned[pid] = (returned[pid] ?? 0n) + BigInt(q);
2317	      effective[pid] = (effective[pid] ?? 0n) - BigInt(q); // 未冲销退货抵减有效到货
2318	    }
2319	  }
2320	  const cancelled = nullProto<Record<string, bigint>>();
2321	  for (const [canId, can] of Object.entries(store.cancels)) {
2322	    if (can.poId !== poId) continue;
2323	    const isReversed = Object.values(store.reversals).some((r) => r.orig === canId);
2324	    if (isReversed) continue;
2325	    for (const [pid, q] of Object.entries(can.qty)) cancelled[pid] = (cancelled[pid] ?? 0n) + BigInt(q);
2326	  }
2327	  const po = store.purchases[poId];
2328	  const remaining = nullProto<Record<string, bigint>>();
2329	  for (const [pid, ordered] of Object.entries(po.ordered)) {
2330	    remaining[pid] = BigInt(ordered) - (effective[pid] ?? 0n) - (cancelled[pid] ?? 0n);
2331	  }
2332	  return { effective, returned, cancelled, remaining };
2333	}
