2607	/**
2608	 * 跨仓补货建议（只读计算，不写文件、不改库存或采购；同状态结果一致）：
2609	 * 每个已配置（商品, 仓库）组合的预计量 = 本仓实存 + 本仓待到货合计
2610	 * （收货仓为本仓的全部采购单：待到货 = 订购 - 有效到货 - 有效取消，不限供应商；
2611	 * 其他仓库存不计入）。预计量不高于下限才触发，缺口 = 目标 - 预计量。
2612	 * 按商品分别分配：同商品其他已配置仓实存超过自身目标的部分可供调拨（待收不可调，
2613	 * 未配置仓既不产生需求也不提供调拨）；缺货仓、来源仓各按标识升序依次取量，
2614	 * 整份建议对来源的累计分配不超过可供量；剩余缺口即采购量。
2615	 * 合计、比较与分配一律用 BigInt 精确整数计算。
2616	 */
2617	function computeReplenish(store: Store): ReplenishSuggestion[] {
2618	  // 各（商品, 仓库）组合的待到货合计：按采购单收货仓归集（不限供应商）
2619	  const pendingByCombo = nullProto<Record<string, Record<string, bigint>>>();
2620	  for (const poId of Object.keys(store.purchases)) {
2621	    const po = store.purchases[poId];
2622	    const { remaining } = purchaseProgress(store, poId); // 待到货 = 订购 - 有效到货 - 有效取消
2623	    for (const [pid, wait] of Object.entries(remaining)) {
2624	      if (wait === 0n) continue;
2625	      const byWh = (pendingByCombo[pid] ??= nullProto<Record<string, bigint>>());
2626	      byWh[po.wh] = (byWh[po.wh] ?? 0n) + wait;
2627	    }
2628	  }
2629	
2630	  const combos: ReplenishSuggestion[] = [];
2631	  for (const pid of Object.keys(store.rules).sort()) {
2632	    for (const wh of Object.keys(store.rules[pid]).sort()) {
2633	      const rule = store.rules[pid][wh];
2634	      const onHand = getStock(store.stock, pid, wh); // 无库存记录视为零
2635	      const pending = pendingByCombo[pid]?.[wh] ?? 0n;
2636	      const projected = BigInt(onHand) + pending;
2637	      const triggered = projected <= BigInt(rule.min); // 不高于下限才触发
2638	      combos.push({
2639	        pid, wh, min: rule.min, target: rule.target, onHand, pending, projected,
2640	        triggered, gap: triggered ? BigInt(rule.target) - projected : 0n,
2641	        transfers: [], transferTotal: 0n, purchase: 0n,
2642	      });
2643	    }
2644	  }
2645	
2646	  // 按商品分别分配调拨：缺货仓与来源仓均按标识升序（combos 已按商品、仓库升序）
2647	  const byProduct = new Map<string, ReplenishSuggestion[]>();
2648	  for (const c of combos) {
2649	    const list = byProduct.get(c.pid) ?? [];
2650	    list.push(c);
2651	    byProduct.set(c.pid, list);
2652	  }
2653	  for (const list of byProduct.values()) {
2654	    // 可供调拨量 = 实存 - 自身目标（仅实存超过目标的部分；待收不可调）
2655	    const sources = list
2656	      .filter((c) => BigInt(c.onHand) > BigInt(c.target))
2657	      .map((c) => ({ wh: c.wh, available: BigInt(c.onHand) - BigInt(c.target) }));
2658	    for (const deficit of list) {
2659	      if (!deficit.triggered) continue;
2660	      let rest = deficit.gap;
2661	      for (const src of sources) {
2662	        if (rest === 0n) break;
2663	        if (src.wh === deficit.wh || src.available === 0n) continue; // 缺货仓实存必低于目标，防御性跳过
2664	        const take = src.available < rest ? src.available : rest;
2665	        deficit.transfers.push({ from: src.wh, qty: take });
2666	        deficit.transferTotal += take;
2667	        src.available -= take; // 整份建议对来源的累计分配不超过可供量
2668	        rest -= take;
2669	      }
2670	      deficit.purchase = rest; // 剩余缺口即采购量（可为零）
2671	    }
2672	  }
2673	  return combos;
2674	}
2675	
2676	function runReplenish(rest: string[], store: Store): void {
2677	  const args = parseArgs(rest, []);
2678	  if (args.positionals.length > 0) throw new UsageError('用法：replenish');
2679	  if (Object.keys(store.rules).length === 0) {
2680	    console.log('未配置任何补货规则，无补货建议（可先用 rule set 为商品与仓库设置下限与目标）。');
2681	    return;
2682	  }
2683	  const combos = computeReplenish(store);
2684	  const triggeredCount = combos.filter((c) => c.triggered).length;
2685	  console.log(`补货建议（规则 ${combos.length} 条，触发 ${triggeredCount} 条）：`);
2686	  for (const c of combos) {
2687	    console.log(
2688	      `商品 ${c.pid} 仓库 ${c.wh}：下限 ${c.min}，目标 ${c.target}，实存 ${c.onHand}，` +
2689	        `待到货合计 ${c.pending}，预计量 ${c.projected}，` +
2690	        (c.triggered ? `触发补货，缺口 ${c.gap}` : '未触发'),
2691	    );
2692	    if (c.triggered) {
2693	      for (const t of c.transfers) console.log(`  调拨 ${t.from} -> ${c.wh}：${t.qty}`);
2694	      console.log(`  调拨合计 ${c.transferTotal}，采购量 ${c.purchase}`);
2695	    }
2696	  }
2697	  if (triggeredCount === 0) console.log('所有组合预计量均高于下限，无缺货，无需补货。');
2698	}
