2739	/**
2740	 * 整批导入：按列表顺序在同一份草稿上处理各项，后项可见前项生效结果；
2741	 * 任一项失败整批拒绝（此前已保存的单据不撤销，本批任何变动均不落库）。
2742	 * 全部重复时不改写数据。逐项输出编号、首次生效/重复（及重复来源）状态与提交结果。
2743	 */
2744	function runImport(rest: string[], dataDir: string): void {
2745	  const args = parseArgs(rest, ['--file']);
2746	  const file = args.flags['--file'];
2747	  if (file === undefined || args.positionals.length > 0)
2748	    throw new UsageError('用法：import --file <单据列表 JSON 文件>');
2749	
2750	  // 先完整读取并解析文件：文件不可读/解析失败时绝不触碰已提交状态
2751	  const requests = parseImportFile(readImportFile(file));
2752	
2753	  // 参数与文件格式均确认无误后才打开本地数据；损坏数据在此被拒绝且不报告成功
2754	  const store = loadStore(dataDir);
2755	  const ledger = new Ledger(store);
2756	  // 模拟阶段收集输出：只有整批通过并完成保存后才向用户报告，绝不报告部分成功
2757	  const blocks: string[] = [];
2758	  let newCount = 0;
2759	
2760	  requests.forEach((r, i) => {
2761	    const pos = `第 ${i + 1}/${requests.length} 项`;
2762	    // 模拟阶段的业务拒绝同样标注列表位置与原因
2763	    const apply = (): ApplyOutcome => {
2764	      switch (r.kind) {
2765	        case 'doc': return ledger.applyDoc(r.req);
2766	        case 'count': return ledger.applyCount(r.req);
2767	        case 'reverse': return ledger.applyReversal(r.docId, r.orig);
2768	        case 'po': return ledger.applyPurchase(r.req);
2769	        case 'arrival': return ledger.applyArrival(r.req);
2770	        case 'cancel': return ledger.applyCancel(r.req);
2771	        case 'return': return ledger.applyReturn(r.req);
2772	      }
2773	    };
2774	    let outcome: ApplyOutcome;
2775	    try {
2776	      outcome = apply();
2777	    } catch (e) {
2778	      if (e instanceof BizError) throw new BizError(`第 ${i + 1} 项：${e.message}`);
2779	      throw e;
2780	    }
2781	    const id =
2782	      r.kind === 'reverse' ? r.docId
2783	      : r.kind === 'po' ? r.req.poId
2784	      : r.kind === 'arrival' ? r.req.arrId
2785	      : r.kind === 'cancel' ? r.req.canId
2786	      : r.kind === 'return' ? r.req.retId
2787	      : r.req.docId;
2788	
2789	    let status: string;
2790	    if (outcome.duplicate) {
2791	      const where = outcome.repeatedFrom === 'batch' ? '（本批此前已出现）' : '（导入前已存在）';
2792	      status = `重复${where}，返回原提交结果，不重新核对库存、不追加流水`;
2793	    } else {
2794	      status = '首次生效';
2795	      newCount++;
2796	    }
2797	    blocks.push([`[${pos}] 单据 ${id}：${status}`, outcome.header, ...outcome.lines].join('\n'));
2798	  });
2799	
2800	  // 全部项通过：有新生效单据时整批一次性保存；全部重复则不改写数据
2801	  ledger.commit(dataDir);
2802	
2803	  console.log(`整批导入完成：共 ${requests.length} 项，首次生效 ${newCount} 项，重复 ${requests.length - newCount} 项。`);
2804	  for (const block of blocks) console.log(block);
2805	}
