          m[wh] = v;
        }
        if (Object.keys(m).length !== Object.keys(snapRules[pid]).length)
          throw bad(`方案 ${planId} 快照待到货与规则不一致`);
        snapPending[pid] = m;
      }
      if (
        Object.keys(snapStock).length !== Object.keys(snapRules).length ||
