        }
      } else if (rec.execResultLines !== undefined) {
        throw bad(`待执行方案 ${planId} 不应携带落单结果`);
      }

      store.plans[planId] = {
        planId, transfers, purchases,
        snapshot: { rules: snapRules, stock: snapStock, pending: snapPending },
        status: rec.status,
        ...(execResultLines !== undefined ? { execResultLines } : {}),
      };
    }
  }

  return store;
}

